-- 110: Original BrillaPrep 4CH1 beta questions, part 2.
-- Original practice content; not official Pearson questions.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_021', 'topic_edx_4ch1_3', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What happens to temperature in an exothermic reaction mixture?', 'multiple_choice', '["A. It increases as energy is transferred to the surroundings","B. It always falls","C. It remains exactly constant","D. It reaches absolute zero"]', 'A', 'Exothermic reactions release energy, often causing the reaction mixture and surroundings to warm. Therefore the correct answer is A: It increases as energy is transferred to the surroundings.', 'hard', 1, 1, 90, 'st_edx_4ch1_3', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_022', 'topic_edx_4ch1_3', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Why does increasing temperature usually increase reaction rate?', 'multiple_choice', '["A. Particles become larger","B. Particles collide more often and more exceed activation energy","C. Activation energy becomes zero","D. Concentration always decreases"]', 'B', 'Higher kinetic energy increases collision frequency and the fraction of successful collisions. Therefore the correct answer is B: Particles collide more often and more exceed activation energy.', 'easy', 2, 2, 90, 'st_edx_4ch1_3', 'Explain', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_023', 'topic_edx_4ch1_3', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'How does a catalyst increase reaction rate?', 'multiple_choice', '["A. It increases product energy permanently","B. It is consumed completely","C. It provides a pathway with lower activation energy","D. It changes the equilibrium constant"]', 'C', 'A lower-energy route allows a greater fraction of collisions to lead to reaction. Therefore the correct answer is C: It provides a pathway with lower activation energy.', 'medium', 1, 1, 90, 'st_edx_4ch1_3', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_024', 'topic_edx_4ch1_3', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'For an equilibrium, what does “dynamic” mean?', 'multiple_choice', '["A. All particles stop moving","B. Reactant and product amounts must be equal","C. Only the forward reaction occurs","D. Forward and reverse reactions continue at equal rates"]', 'D', 'At dynamic equilibrium both reactions continue, but equal rates keep macroscopic concentrations constant. Therefore the correct answer is D: Forward and reverse reactions continue at equal rates.', 'hard', 2, 2, 90, 'st_edx_4ch1_3', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_025', 'topic_edx_4ch1_3', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Increasing pressure favours which side of a gaseous equilibrium?', 'multiple_choice', '["A. The side with fewer gas molecules","B. The side with more gas molecules","C. The side with more solids","D. Neither side under any condition"]', 'A', 'The system reduces pressure by shifting toward the side containing fewer moles of gas. Therefore the correct answer is A: The side with fewer gas molecules.', 'easy', 3, 3, 90, 'st_edx_4ch1_3', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_026', 'topic_edx_4ch1_3', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What is the effect of increasing concentration of a reactant?', 'multiple_choice', '["A. Particles stop colliding","B. More frequent collisions generally increase rate","C. Activation energy doubles","D. The reactant becomes a catalyst"]', 'B', 'More reactant particles per unit volume increases collision frequency and therefore reaction rate. Therefore the correct answer is B: More frequent collisions generally increase rate.', 'medium', 2, 2, 90, 'st_edx_4ch1_3', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_027', 'topic_edx_4ch1_3', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Which bond-energy calculation gives reaction enthalpy?', 'multiple_choice', '["A. Energy formed minus energy broken","B. All bond energies multiplied","C. Energy to break bonds minus energy released forming bonds","D. Product mass minus reactant mass"]', 'C', 'Bond breaking absorbs energy and bond formation releases it, so the difference gives the overall change. Therefore the correct answer is C: Energy to break bonds minus energy released forming bonds.', 'hard', 1, 1, 90, 'st_edx_4ch1_3', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_028', 'topic_edx_4ch1_3', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Why does powdered solid react faster than equal-mass lumps?', 'multiple_choice', '["A. It has fewer particles","B. It lowers product concentration","C. It stops diffusion","D. It has a larger surface area"]', 'D', 'Greater exposed surface permits more reactant collisions per second. Therefore the correct answer is D: It has a larger surface area.', 'easy', 2, 2, 90, 'st_edx_4ch1_3', 'Explain', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_029', 'topic_edx_4ch1_3', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'In the Haber process, why is a compromise temperature used?', 'multiple_choice', '["A. It balances equilibrium yield and reaction rate","B. It removes the catalyst","C. It makes pressure irrelevant","D. It prevents all reverse reaction"]', 'A', 'Lower temperature favours ammonia yield but slows reaction, so industry chooses an economic compromise. Therefore the correct answer is A: It balances equilibrium yield and reaction rate.', 'medium', 1, 1, 90, 'st_edx_4ch1_3', 'Explain', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_030', 'topic_edx_4ch1_3', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What does a reaction-profile peak represent?', 'multiple_choice', '["A. The final product mass","B. The activation energy barrier","C. The catalyst concentration","D. The equilibrium yield"]', 'B', 'The peak is the high-energy transition region reactant particles must reach for reaction. Therefore the correct answer is B: The activation energy barrier.', 'hard', 3, 3, 90, 'st_edx_4ch1_3', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_031', 'topic_edx_4ch1_4', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What is the general formula of an alkane?', 'multiple_choice', '["A. CₙH₂ₙ","B. CₙH₂ₙ₋₂","C. CₙH₂ₙ₊₂","D. CₙHₙ"]', 'C', 'Open-chain saturated hydrocarbons have the homologous-series formula CₙH₂ₙ₊₂. Therefore the correct answer is C: CₙH₂ₙ₊₂.', 'easy', 1, 1, 90, 'st_edx_4ch1_4', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_032', 'topic_edx_4ch1_4', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Which observation shows an alkene reacted with bromine water?', 'multiple_choice', '["A. A white precipitate forms","B. A glowing splint relights","C. The solution turns blue","D. Orange bromine water becomes colourless"]', 'D', 'Bromine adds across the carbon-carbon double bond, removing its orange colour. Therefore the correct answer is D: Orange bromine water becomes colourless.', 'medium', 2, 2, 90, 'st_edx_4ch1_4', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_033', 'topic_edx_4ch1_4', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What are the products of complete hydrocarbon combustion?', 'multiple_choice', '["A. Carbon dioxide and water","B. Carbon monoxide only","C. Carbon and hydrogen","D. Methane and oxygen"]', 'A', 'With sufficient oxygen, carbon is fully oxidised to carbon dioxide and hydrogen to water. Therefore the correct answer is A: Carbon dioxide and water.', 'hard', 1, 1, 90, 'st_edx_4ch1_4', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_034', 'topic_edx_4ch1_4', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Which functional group is present in ethanol?', 'multiple_choice', '["A. Carboxyl, −COOH","B. Hydroxyl, −OH","C. Carbon-carbon double bond","D. Ester link only"]', 'B', 'Ethanol belongs to the alcohol homologous series because it contains an −OH group. Therefore the correct answer is B: Hydroxyl, −OH.', 'easy', 2, 2, 90, 'st_edx_4ch1_4', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_035', 'topic_edx_4ch1_4', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Oxidation of ethanol can produce which carboxylic acid?', 'multiple_choice', '["A. Methanoic acid","B. Propanoic acid","C. Ethanoic acid","D. Butanoic acid"]', 'C', 'A two-carbon primary alcohol oxidises to the corresponding two-carbon carboxylic acid. Therefore the correct answer is C: Ethanoic acid.', 'medium', 3, 3, 90, 'st_edx_4ch1_4', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_036', 'topic_edx_4ch1_4', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What forms when an alcohol reacts with a carboxylic acid?', 'multiple_choice', '["A. An alkane and hydrogen","B. A metal and oxygen","C. Only carbon dioxide","D. An ester and water"]', 'D', 'Esterification is a condensation reaction joining the two molecules and releasing water. Therefore the correct answer is D: An ester and water.', 'hard', 2, 2, 90, 'st_edx_4ch1_4', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_037', 'topic_edx_4ch1_4', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What monomer makes poly(ethene)?', 'multiple_choice', '["A. Ethene","B. Ethane","C. Ethanol","D. Ethanoic acid"]', 'A', 'Ethene molecules open their double bonds and join in addition polymerisation. Therefore the correct answer is A: Ethene.', 'easy', 1, 1, 90, 'st_edx_4ch1_4', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_038', 'topic_edx_4ch1_4', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What process separates crude oil into useful fractions?', 'multiple_choice', '["A. Filtration","B. Fractional distillation","C. Neutralisation","D. Electrolysis"]', 'B', 'Hydrocarbons separate by different boiling ranges in a fractionating column. Therefore the correct answer is B: Fractional distillation.', 'medium', 2, 2, 90, 'st_edx_4ch1_4', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_039', 'topic_edx_4ch1_4', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'Why is cracking useful?', 'multiple_choice', '["A. It removes all carbon atoms","B. It makes only water","C. It converts long hydrocarbons into shorter alkanes and alkenes","D. It joins monomers into proteins"]', 'C', 'Cracking supplies higher-demand fuels and reactive alkene feedstocks from heavier fractions. Therefore the correct answer is C: It converts long hydrocarbons into shorter alkanes and alkenes.', 'hard', 1, 1, 90, 'st_edx_4ch1_4', 'Explain', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ch1_b001_040', 'topic_edx_4ch1_4', 'subj_edexcel_igcse_chemistry', 'edexcel_igcse', 'What feature defines members of a homologous series?', 'multiple_choice', '["A. Identical molecular formula","B. Exactly the same boiling point","C. No trend in properties","D. Same functional group and general formula"]', 'D', 'Members share a functional group and general formula, with successive compounds differing by CH₂. Therefore the correct answer is D: Same functional group and general formula.', 'easy', 3, 3, 90, 'st_edx_4ch1_4', 'Identify', 'AO1', 'board_edexcel');
